def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = 0
    my_def = 0
    for a, b in history:
        if b == 'D':
            opp_def += 1
        if a == 'D':
            my_def += 1

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # If opponent is extremely defective, defect
    if n >= 10:
        if opp_def / n > 0.8:
            return 'D'
        if opp_def / n > 0.5 and opp_last == 'D':
            return 'D'

    # Tit-for-two-tats: defect if opponent defected last two rounds
    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            # If we also defected last round, consider breaking the cycle
            if my_last == 'D':
                # If opponent is not too defective overall, try to cooperate to restore mutual cooperation
                if opp_def / n < 0.4:
                    return 'C'
                else:
                    return 'D'
            return 'D'

    # Endgame: defect last two rounds
    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    # Default: cooperate (forgiving single defection)
    return 'C'
